//
// The stretch Worker: one render per message, off the main thread.
//
// WHY A SECOND WORKER AND NOT THE SPECTRUM ONE (ADR 0023 decision 2).
// `dsp/pipeline.ts` keeps a module-global plan cache whose entries hold shared
// mutable scratch keyed by `(window, length, fft_size)`. A render running in
// the spectrum Worker at a size a live preset also uses would write into the
// live frame's buffers — and a multi-second synchronous loop there would stall
// every column for its duration. A second Worker is a second module instance,
// so the isolation is structural rather than a rule somebody has to remember.
// This file imports `dsp/fft.ts`, `dsp/stretch*.ts` and its own protocol, and
// NEVER `dsp/pipeline.ts`.
//
// THE LOOP IS SYNCHRONOUS ON PURPOSE. There is no main thread here to block,
// and yielding would only add scheduling noise to a measurement the validation
// block reports. Progress is posted from inside it; `postMessage` from a
// Worker is delivered while the sender is still busy, which is what makes a
// progress bar possible without a single `await`.
// ----------------------------------------------------------------------------

import { defaultStretchParams, stretchRender } from '../dsp/stretch';
import { unityRmsGain } from '../dsp/stretch-window';
import { stretchWindow } from '../dsp/stretch-window';
import {
  capRefusal,
  stretchTransferables,
  type StretchRequest,
  type StretchResponse,
} from './stretch-protocol';

const scope = self as unknown as {
  postMessage: (message: StretchResponse, transfer?: Transferable[]) => void;
  addEventListener: (type: 'message', listener: (event: MessageEvent<StretchRequest>) => void) => void;
};

function render(request: StretchRequest): void {
  const { id, channels, sampleRateHz, stretch, windowSamples, seed, circular } = request;
  const first = channels[0];
  if (first === undefined || first.length === 0) {
    scope.postMessage({ type: 'refused', id, reason: 'params', message: 'the region is empty' });
    return;
  }

  // Before any allocation: the cap is arithmetic, and a Worker that had
  // already built a 600 s buffer to be told it may not have one would be
  // holding the memory the cap exists to protect.
  const refusal = capRefusal(id, first.length, sampleRateHz, stretch, windowSamples);
  if (refusal !== null) {
    scope.postMessage(refusal);
    return;
  }

  const gain = unityRmsGain(stretchWindow(windowSamples));
  const params = { ...defaultStretchParams(sampleRateHz, stretch), windowSamples, seed, circular, gain };

  const startedAt = performance.now();
  const rendered = channels.map((channel, index) =>
    // One phase stream per channel would widen a mono stem into a stereo cloud
    // — wider than what the analysis node hears, which is the down-mix (ADR
    // 0023 decision 7, the owner's choice on 2026-08-23). The shell sends one
    // channel; if it ever sends two they share a seed and stay centred.
    stretchRender(channel, params, index === 0
      ? (doneSamples, totalSamples) => { scope.postMessage({ type: 'progress', id, doneSamples, totalSamples }); }
      : undefined),
  );
  const renderMs = performance.now() - startedAt;

  const first_ = rendered[0];
  if (first_ === undefined) {
    scope.postMessage({ type: 'error', id, message: 'no channel was rendered' });
    return;
  }
  const out = rendered.map((r) => r.samples);
  scope.postMessage(
    {
      type: 'rendered',
      id,
      channels: out,
      sampleRateHz,
      inputSamples: first_.inputSamples,
      outputSamples: first_.outputSamples,
      steps: first_.steps,
      peakAbs: Math.max(...rendered.map((r) => r.peakAbs)),
      peakGuardDb: Math.min(...rendered.map((r) => r.peakGuardDb)),
      gain,
      renderMs,
      stretch,
      windowSamples,
      seed,
    },
    stretchTransferables(out),
  );
}

scope.addEventListener('message', (event: MessageEvent<StretchRequest>) => {
  const request = event.data;
  try {
    if (request.type === 'render') {
      render(request);
      return;
    }
    scope.postMessage({
      type: 'error',
      id: (request as { id?: number }).id ?? -1,
      message: `unknown request ${JSON.stringify((request as { type?: string }).type)}`,
    });
  } catch (error) {
    // A throw here would surface as an unhandled rejection with no stack that
    // points at the cause; the shell renders this message instead.
    scope.postMessage({
      type: 'error',
      id: request.id ?? -1,
      message: error instanceof Error ? error.message : String(error),
    });
  }
});
