//
// The one window in this application that is not ADR 0006 D1's — and the
// reason D1 does not reach it.
//
// D1 governs ANALYSIS windows: periodic cosine sums built from a preset's own
// coefficients, whose S1 and S2 are pinned because a level readout is computed
// through them. This is a SYNTHESIS window for a signal nobody measures a level
// from (ADR 0023 decision 5). It is not a cosine sum, it is symmetric rather
// than periodic, and the property that matters for it is one D1 never mentions.
//
// THE CONDITION IS ON w², NOT ON w. Overlap-add usually wants
// `Σ_m w[n − mH] = const` — the COLA condition — because consecutive frames
// add coherently. Here they do not: every frame is resynthesised with fresh
// random phases, so consecutive frames are mutually incoherent and their
// POWERS add. The flatness condition is therefore `Σ_m w²[n − mH] = const`,
// and the two are not satisfied by the same windows. Periodic Hann at 50 % is
// exactly COLA (`Σw = 1`) and badly not power-complementary (`Σw² ∈ [0.5, 1]`),
// which is 3.01 dB of amplitude flutter at twice the frame rate — audible as a
// tremolo, and the defect the reference implementation patches with a
// correction curve. `(1 − x²)^1.25` needs no correction: measured
// `Σw² ∈ [0.9741, 1.0000]`, a 0.114 dB ripple (numpy, 2026-08-23, N = 8192).
// `windowIsPowerComplementary` below is that measurement as a function, and
// the unit test asserts Hann FAILS it so nobody "simplifies" the window away.
//
// PROVENANCE. The window is Nasca Octavian Paul's, from `paulstretch_stereo.py`
// — his last word on the subject, the 2011-05-07 commit whose message is
// "Added better windowing function and which prevents unwanted amplitude
// modulation". That file is public domain ([06 #67]: "The Paulstretch algorithm
// is released under Public Domain"). What is taken is the formula, which is one
// expression; the code around it is not.
//
// WHY IT IS NOT IN `window.ts`. That module's `WINDOW_FAMILIES` is pinned
// digit-for-digit to `preset-schema.md` §4.3 by a golden test, its evaluator
// only understands cosine sums, and `pipeline.ts` refuses any window not in
// the table. Putting a non-cosine synthesis window there would make three true
// sentences false. `windowSums` is imported FROM there, because S1/S2 mean the
// same thing for any window and a second implementation of a sum is a second
// place to get it wrong.
// ----------------------------------------------------------------------------

import { windowSums, type WindowSums } from './window';

/**
 * The exponent. `(1 − x²)^1.25` — not 1.0 (which is not flat enough) and not
 * 1.5 (which is flatter in the sum and narrower in the main lobe, but is not
 * the reference's and would make our drone a different sound from every other
 * Paulstretch a singer has heard). `(prov.)` in the sense that ADR 0023 owns
 * it; it is not a tuning knob.
 */
export const STRETCH_WINDOW_EXPONENT = 1.25;

/**
 * `w[j] = (1 − x_j²)^1.25` with `x_j = −1 + 2j/(n−1)`, in float64.
 *
 * SYMMETRIC, `n − 1` in the denominator — the opposite of ADR 0006 D1's
 * periodic form, and deliberately so. A periodic window would leave `w[0] = 1`
 * at one end and 0 at the other, which in an overlap-add means a discontinuity
 * at every frame boundary; a synthesis window has to reach zero at BOTH ends.
 * D1's objection to the symmetric form is that it perturbs NENBW, which is a
 * statement about a spectral estimate, and nothing here estimates one.
 *
 * float64 only: there is no device digest for this table and nothing compares
 * it to a golden, so the float32 rounding `window.ts` performs for its own
 * table has nothing to buy here.
 */
export function stretchWindow(n: number): Float64Array {
  if (!Number.isInteger(n) || n < 16 || n % 2 !== 0) {
    throw new RangeError(`the stretch window needs an even integer length >= 16, got ${String(n)}`);
  }
  const w = new Float64Array(n);
  const step = 2 / (n - 1);
  for (let j = 0; j < n; j += 1) {
    const x = -1 + step * j;
    w[j] = Math.pow(1 - x * x, STRETCH_WINDOW_EXPONENT);
  }
  return w;
}

/**
 * `Σ_m w²[j − m·hop]` for one hop of the steady state — the quantity that must
 * be constant for a random-phase overlap-add to have a flat envelope.
 *
 * Returned as the `hop` values it takes across one hop, so a caller can read
 * its min and max (the ripple) rather than being told a verdict.
 */
export function olaPowerSum(w: Float64Array, hop: number): Float64Array {
  if (!Number.isInteger(hop) || hop < 1 || hop > w.length) {
    throw new RangeError(`hop must be an integer in [1, ${String(w.length)}], got ${String(hop)}`);
  }
  const sum = new Float64Array(hop);
  for (let j = 0; j < hop; j += 1) {
    let total = 0;
    for (let start = j; start < w.length; start += hop) {
      const value = w[start] as number;
      total += value * value;
    }
    sum[j] = total;
  }
  return sum;
}

/** The ripple of that sum, in dB: `10·log10(max/min)`. 0 for a perfectly flat window. */
export function olaRippleDb(w: Float64Array, hop: number): number {
  const sum = olaPowerSum(w, hop);
  let min = Infinity;
  let max = 0;
  for (const value of sum) {
    if (value < min) {
      min = value;
    }
    if (value > max) {
      max = value;
    }
  }
  return min > 0 ? 10 * Math.log10(max / min) : Infinity;
}

/**
 * The makeup gain that brings a random-phase overlap-add back to unity RMS:
 * `1/√mean(w²)`.
 *
 * Where it comes from. Phase randomisation preserves each windowed frame's
 * energy (Parseval), and the inverse transform spreads it uniformly over the
 * frame, so the pre-synthesis RMS of a frame whose input had RMS σ is
 * `σ·√mean(w²)`. The synthesis window and the incoherent overlap-add then
 * contribute an envelope of `√(Σw²) ≈ 1` — which is what the window's
 * power-complementarity buys. What is left is exactly the `√mean(w²)`, and
 * this undoes it. Measured end to end: −3.17 dB before, −0.08 dB after.
 *
 * For `(1 − x²)^1.25` the closed form is `√(32/5π) = 1.4272…`; the discrete
 * value at N = 8192 is 1.4274.
 */
export function unityRmsGain(w: Float64Array): number {
  let total = 0;
  for (const value of w) {
    total += value * value;
  }
  return 1 / Math.sqrt(total / w.length);
}

/** S1/S2/NENBW of this window, through `window.ts`'s own sums — never a second implementation. */
export function stretchWindowSums(w: Float64Array): WindowSums {
  return windowSums(w);
}
