//
// The messages between the shell and the stretch Worker.
//
// ITS OWN PROTOCOL, not an extension of `protocol.ts`'s union. Adding a
// `render` request to `WorkerRequest` would typecheck — and would then say
// that the spectrum Worker accepts a message it has never heard of, and that
// this Worker accepts hops it does not. Two Workers, two vocabularies, and a
// reader can tell from the import which one a message belongs to.
//
// WHY THE CAP LIVES ON THIS SIDE OF THE BOUNDARY. `stretchOutputLength` is
// arithmetic and needs no audio, so the refusal is computed before a single
// float is allocated — the Worker never holds a buffer it is about to be told
// it may not have. The shell could compute it too; it does not, because then
// two places would own the number.
// ----------------------------------------------------------------------------

import { STRETCH_CAP_S, stretchOutputLength } from '../dsp/stretch';

export interface StretchRenderRequest {
  readonly type: 'render';
  /** Echoed in every reply, so a late answer to a superseded request is discardable. */
  readonly id: number;
  /** One entry per channel, TRANSFERRED — the region only, sliced by the shell. */
  readonly channels: Float32Array[];
  readonly sampleRateHz: number;
  readonly stretch: number;
  readonly windowSamples: number;
  readonly seed: number;
  readonly circular: boolean;
}

export type StretchRequest = StretchRenderRequest;

export interface StretchProgress {
  readonly type: 'progress';
  readonly id: number;
  readonly doneSamples: number;
  readonly totalSamples: number;
}

export interface StretchRendered {
  readonly type: 'rendered';
  readonly id: number;
  /** One entry per channel, TRANSFERRED back. */
  readonly channels: Float32Array[];
  readonly sampleRateHz: number;
  readonly inputSamples: number;
  readonly outputSamples: number;
  readonly steps: number;
  readonly peakAbs: number;
  readonly peakGuardDb: number;
  readonly gain: number;
  readonly renderMs: number;
  readonly stretch: number;
  readonly windowSamples: number;
  readonly seed: number;
}

export interface StretchRefused {
  readonly type: 'refused';
  readonly id: number;
  readonly reason: 'cap' | 'params';
  readonly message: string;
}

export interface StretchFailed {
  readonly type: 'error';
  readonly id: number;
  readonly message: string;
}

export type StretchResponse = StretchProgress | StretchRendered | StretchRefused | StretchFailed;

/**
 * Would this render exceed the cap? Arithmetic only — no allocation, no audio.
 *
 * `null` when it fits; a refusal carrying BOTH numbers when it does not,
 * because "too long" without a length is a message a singer cannot act on.
 */
export function capRefusal(
  id: number,
  inputSamples: number,
  sampleRateHz: number,
  stretch: number,
  windowSamples: number,
  capS: number = STRETCH_CAP_S,
): StretchRefused | null {
  const outputSamples = stretchOutputLength(inputSamples, stretch, windowSamples);
  const outputS = outputSamples / sampleRateHz;
  if (outputS <= capS) {
    return null;
  }
  const megabytes = (outputSamples * 4) / 1_000_000;
  return {
    type: 'refused',
    id,
    reason: 'cap',
    message:
      `${(inputSamples / sampleRateHz).toFixed(1)} s at ${stretch.toFixed(1)}× is ` +
      `${outputS.toFixed(0)} s of audio (${megabytes.toFixed(0)} MB); the cap is ${String(capS)} s — ` +
      'shorten the loop or lower the factor',
  };
}

/** The transferable list for a reply. `Float32Array.buffer` is `ArrayBufferLike`; the cast is `protocol.ts`'s. */
export function stretchTransferables(channels: readonly Float32Array[]): Transferable[] {
  return channels.map((channel) => channel.buffer as ArrayBuffer);
}
